/// Rank players by score and return the top k, keeping ties.
/// entries are (name, score) pairs. A name may appear several times; only
/// its highest score counts. Entries whose name is the empty string are
/// ignored. Names are compared exactly (case and spaces matter).
/// Each distinct name gets a competition rank: 1 plus the number of names
/// with a strictly higher best score (so best scores 9, 7, 7, 5 get ranks
/// 1, 2, 2, 4). Return (rank, name, score) for every name whose rank is at
/// most k, which can be more than k names when there are ties at the cut,
/// sorted by score descending and then by name ascending (plain character
/// order).
/// If k is less than 1, return an empty vector.
/// >>> top_k(vec![(String::from("ann"), 5), (String::from("bob"), 9), (String::from("cy"), 7), (String::from("dee"), 7)], 2)
/// vec![(1, String::from("bob"), 9), (2, String::from("cy"), 7), (2, String::from("dee"), 7)]
/// >>> top_k(vec![(String::from("ann"), 3), (String::from("ann"), 8), (String::from("bob"), 8), (String::from("cy"), 1)], 2)
/// vec![(1, String::from("ann"), 8), (1, String::from("bob"), 8)]
fn top_k(entries: Vec<(String, i64)>, k: i64) -> Vec<(i64, String, i64)> {
    if k < 1 {
        return Vec::new();
    }
    let mut best: Vec<(String, i64)> = Vec::new();
    for (name, score) in entries {
        if name.is_empty() {
            continue;
        }
        match best.iter_mut().find(|b| b.0 == name) {
            Some(b) => {
                if score > b.1 {
                    b.1 = score;
                }
            }
            None => best.push((name, score)),
        }
    }
    best.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    let mut out = Vec::new();
    for (name, score) in best.iter() {
        let rank = 1 + best.iter().filter(|b| b.1 > *score).count() as i64;
        if rank > k {
            break;
        }
        out.push((rank, name.clone(), *score));
    }
    out
}
